/**
 *
 * MenuGroup wraps a logical group of menu items. Renders with role="group" and
 * exposes its id so a nested Menu.Label can be linked via aria-labelledby.
 *
 * [Live Demo](https://www.primereact.org/menu/)
 *
 * @module MenuGroup
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { MenuRootInstance } from './MenuRoot.types';
/**
 * Defines passthrough(pt) options type in MenuGroup component.
 */
export type MenuGroupPassThroughType<E> = PassThroughType<MenuGroupInstance, E>;
/**
 * Defines passthrough(pt) options of MenuGroup component.
 */
export interface MenuGroupPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: MenuGroupPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Context value shared between MenuGroup and a nested MenuLabel so the label
 * id can be attached to the group's `aria-labelledby`.
 */
export interface MenuGroupContextInterface {
    /**
     * The id of the group element.
     */
    groupId: string | undefined;
    /**
     * The id of the nested label element, when present.
     */
    labelId: string | undefined;
    /**
     * Setter used by a nested Menu.Label to register its id with the group.
     */
    setLabelId: (id: string | undefined) => void;
}
/**
 * Defines valid properties in MenuGroup component.
 */
export interface MenuGroupProps extends BaseComponentProps<MenuGroupInstance, unknown, MenuGroupPassThrough> {
}
/**
 * Defines valid state in MenuGroup component.
 */
export interface MenuGroupState {
}
/**
 * Defines the methods and properties exposed by MenuGroup component.
 */
export interface MenuGroupExposes {
    /**
     * Instance of the Menu component.
     */
    menu: MenuRootInstance | undefined | null;
    /**
     * Context exposed to nested Menu.Label children.
     */
    context: MenuGroupContextInterface;
}
/**
 * Instance of MenuGroup component.
 */
export type MenuGroupInstance = ComponentInstance<MenuGroupProps, MenuGroupState, MenuGroupExposes>;
